pub fn def(id: CardId) -> &'static CardDef {
    CARDS
        .iter()
        .find(|c| c.id == id)
        .expect("every CardId has a catalog entry")
}

pub fn by_name(name: &str) -> Option<CardId> {
    let needle = name.trim();
    CARDS
