    let mut cards = vec![(catalog::by_name("Jasmine Boreal").unwrap(), 1u8)];
    cards.push((CardId::Forest, 39));
    let deck = DeckList::new("bad", cards);
    let err = Game::new(1, &[deck.clone(), deck]).expect_err("engine must refuse it too");
