#[test]
fn every_pool_card_added_after_issue_15_has_a_recorded_printing() {
    let starter: Vec<Value> = starter_new_cards()
        .into_iter()
        .chain(krenko_new_cards())
        .collect();
    let starter_names: Vec<&str> = starter
        .iter()
        .map(|card| sourced_text(card, "name"))
        .collect();
