        if game.state.stack.is_empty() && game.state.trigger_queue.is_empty() {
            break;
        }
        let player = game.decision_owner().expect("priority");
        events.extend(submit_ok(&mut game, player, Action::Pass));
    }
    assert_eq!(game.state.player(P0).life, life + 1, "the queued trigger still gains life");
    assert!(
        game.state.players.iter().any(|p| p.hand.iter().any(|id| game.state.object(*id).card == card("Tatyova, Benthic Druid"))),
        "the source was returned to hand through a real spell"
    );
    let life_at = events.iter().position(|e| matches!(e, Event::LifeChange { player: P0, delta: 1, .. }));
    let draw_at = events.iter().position(|e| matches!(e, Event::Draw { player: P0, .. }));
    let resolved_at = events.iter().position(|e| matches!(e, Event::AbilityResolved { card, .. } if *card == card("Tatyova, Benthic Druid")));
    assert!(life_at < draw_at && draw_at < resolved_at, "life then draw then resolved: {events:?}");
    assert!(
        !events[life_at.unwrap()..=resolved_at.unwrap()]
            .iter()
            .any(|e| matches!(e, Event::Priority { .. })),
        "no priority between gain-life, draw and AbilityResolved"
    );
}

