use aperture_core::*;
use common::*;

fn card(name: &str) -> CardId {
    catalog::by_name(name).unwrap_or_else(|| panic!("{name} must be supported"))
}
fn drain(g: &mut Game) {
    for _ in 0..96 {
        if g.state.pending.is_some() || g.state.stack.is_empty() { return; }
        let p = g.decision_owner().unwrap();
        submit_ok(g, p, Action::Pass);
