    let new_bear = g.state.battlefield(P0).into_iter().find(|o| o.card == CardId::DragonScarredBear && o.id != bear).expect("new object").id;
    shock(&mut g, new_bear);
    assert_eq!(g.state.object(new_bear).zone, Zone::Graveyard, "shield cannot transfer to a new object");
}

