use aperture_core::*;
use common::*;
fn card(name:&str)->CardId{catalog::by_name(name).unwrap()}
fn land8()->Vec<CardId>{vec![CardId::Forest;8]}
fn drain(g:&mut Game){for _ in 0..128{if g.state.pending.is_some()||g.state.stack.is_empty(){return;}let p=g.decision_owner().unwrap();submit_ok(g,p,Action::Pass);}panic!("settle");}
fn cast(g:&mut Game,id:ObjectId){let a=g.legal_actions().into_iter().find(|a|matches!(a.action,Action::CastSpell{card,..} if card==id)).expect("offered cast").action;submit_ok(g,P0,a);drain(g);}

#[test]
fn surrak_trigger_gives_counter_and_haste_only_to_entered_nontoken_creature() {
    let mut b=land8(); b.push(card("Surrak and Goreclaw"));
    let mut g=fixture(2401).hand(P0,&[card("Surrak and Goreclaw"),card("Grizzly Bears")]).battlefield(P0,&b).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let surrak=hand_card(&g,P0,card("Surrak and Goreclaw"));
    cast(&mut g,surrak);
    let surrak=battlefield_card(&g,P0,card("Surrak and Goreclaw"));
    assert_eq!(g.state.object(surrak).counters.get(aperture_core::counters::CounterKind::PlusOnePlusOne),0,"own entry is not another");
    let bear=hand_card(&g,P0,card("Grizzly Bears"));
    cast(&mut g,bear);
    let bear=battlefield_card(&g,P0,card("Grizzly Bears"));
    assert_eq!(g.state.object(bear).counters.get(aperture_core::counters::CounterKind::PlusOnePlusOne),1);
    assert!(g.state.effects.iter().any(|e|e.kind==ContinuousKind::GrantsHaste&&e.target==bear));
    assert!(g.legal_attackers(P0).contains(&bear),"haste allows the summoning-sick creature to attack");
    assert!(g.state.pending.is_none());
    assert!(g.state.stack.is_empty());
    assert!(g.state.trigger_queue.is_empty());
    assert!(g.state.resolving.is_none());
}

#[test]
fn older_creature_does_not_get_haste_and_cleanup_expires_it() {
    let mut b=land8(); b.push(CardId::GrizzlyBears);
    let mut g=fixture(2402).hand(P0,&[card("Surrak and Goreclaw"),card("Grizzly Bears")]).battlefield(P0,&b).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let old=battlefield_card(&g,P0,CardId::GrizzlyBears);
    let surrak=hand_card(&g,P0,card("Surrak and Goreclaw"));
    cast(&mut g,surrak);
    assert!(!g.state.effects.iter().any(|e|e.kind==ContinuousKind::GrantsHaste&&e.target==old));
    let new=hand_card(&g,P0,card("Grizzly Bears"));
    cast(&mut g,new);
    let new=battlefield_card(&g,P0,card("Grizzly Bears"));
    assert!(g.state.effects.iter().any(|e|e.kind==ContinuousKind::GrantsHaste&&e.target==new));
    let turn=g.state.turn.number;
    for _ in 0..1000 {
        if g.state.turn.number!=turn {break;}
        if g.state.pending.is_some(){let a=auto_answer(&g);let p=g.decision_owner().unwrap();submit_ok(&mut g,p,a);continue;}
        let p=g.decision_owner().unwrap();submit_ok(&mut g,p,Action::Pass);
    }
    assert!(!g.state.effects.iter().any(|e|e.kind==ContinuousKind::GrantsHaste&&e.target==new),"cleanup expires haste");
}
