#[test]
fn static_other_creature_trample_changes_real_combat() {
    let mut b=land8(); b.push(card("Surrak and Goreclaw")); b.push(CardId::GrizzlyBears);
    let mut g=fixture(2403).battlefield(P0,&b).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let bear=battlefield_card(&g,P0,CardId::GrizzlyBears);
    let blocker=add_creature(&mut g,P1,CardId::SoldierToken);
    let life=g.state.player(P1).life;
    let mut log=Vec::new();
    assert!(run_until(&mut g,&mut log,|g|g.state.turn.step==Step::DeclareAttackers&&g.state.pending.is_some(),64));
    submit_ok(&mut g,P0,Action::DeclareAttackers{attackers:vec![bear],defender:Some(P1)});
    assert!(run_until(&mut g,&mut log,|g|g.state.turn.step==Step::DeclareBlockers&&g.state.pending.is_some(),64));
    submit_ok(&mut g,P1,Action::DeclareBlockers{blocks:vec![aperture_core::BlockDecl{blocker,attacker:bear}]});
    assert!(run_until(&mut g,&mut log,|g|g.state.player(P1).life<life,64));
    assert_eq!(g.state.object(blocker).zone,Zone::Graveyard);
    assert_eq!(g.state.player(P1).life,life-1,"trample excess reaches the player");
}

#[test]
fn bounced_entered_creature_loses_old_trigger_and_recast_triggers_once() {
    let mut b=vec![CardId::Forest;12]; b.push(CardId::Island); b.push(card("Surrak and Goreclaw"));
    let mut g=fixture(2404).hand(P0,&[card("Grizzly Bears"),CardId::Unsummon]).battlefield(P0,&b).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let grizzly=hand_card(&g,P0,card("Grizzly Bears"));
    let cast_action=g.legal_actions().into_iter().find(|a|matches!(a.action,Action::CastSpell{card,..} if card==grizzly)).unwrap().action;
    submit_ok(&mut g,P0,cast_action);
    // Resolve only the creature spell; its entry trigger remains on the stack.
    submit_ok(&mut g,P0,Action::Pass);
    submit_ok(&mut g,P1,Action::Pass);
    assert!(!g.state.trigger_queue.is_empty() || !g.state.stack.is_empty());
