    let mut g=fixture(2405).hand(P0,&[card("Surrak and Goreclaw"),card("Grizzly Bears")]).battlefield(P0,&b).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
