    let a=g.legal_actions().into_iter().find(|a|matches!(a.action,Action::CastSpell{card,..} if card==grizzly)).unwrap().action;
    submit_ok(&mut g,P0,a);
    submit_ok(&mut g,P0,Action::Pass); submit_ok(&mut g,P1,Action::Pass);
    assert!(!g.state.stack.is_empty() || !g.state.trigger_queue.is_empty(),"entry trigger is pending");
    let decks=vec![DeckList::parse_practice("A","40 Forest\n").unwrap(),DeckList::parse_practice("B","40 Forest\n").unwrap()];
    let replay=Replay::new(g.state.seed,g.state.first_player,decks,AiSettings::default()).unwrap();
    let save=SessionSave::capture(&g,replay,Vec::new(),true);
    let loaded=SessionSave::from_json(&save.to_json()).expect("midtrigger save loads");
    let mut loaded=Game::from_state(loaded.game).unwrap();
    assert_eq!(loaded.digest(),g.digest());
    drain(&mut g); drain(&mut loaded);
    assert_eq!(loaded.state,g.state);
    assert_eq!(loaded.digest(),g.digest());
    let grizzly=g.state.battlefield(P0).into_iter().find(|o|o.card==CardId::GrizzlyBears).unwrap().id;
    assert_eq!(g.state.object(grizzly).counters.get(aperture_core::counters::CounterKind::PlusOnePlusOne),1);
