use common::*;
fn card25(n:&str)->CardId{catalog::by_name(n).unwrap()}
fn attack_to_choice(g:&mut Game)->(ObjectId,ObjectId){
 let wolf=battlefield_card(g,P0,card25("Exuberant Wolfbear"));
 let human=battlefield_card(g,P0,CardId::EliteVanguard);
 let mut log=Vec::new();
 assert!(run_until(g,&mut log,|g|g.state.turn.step==Step::DeclareAttackers&&g.state.pending.is_some(),64));
 submit_ok(g,P0,Action::DeclareAttackers{attackers:vec![wolf],defender:Some(P1)});
 assert!(run_until(g,&mut log,|g|matches!(g.state.pending,Some(Pending::TriggerChoice{..})),64));
 (wolf,human)
}
fn base_game(seed:u64)->Game{
 fixture(seed).battlefield(P0,&[card25("Exuberant Wolfbear"),CardId::EliteVanguard]).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build()
}

#[test]
fn attack_trigger_sets_human_base_to_current_wolfbear_stats_after_counters() {
 let mut g=base_game(2501);
 let wolf=battlefield_card(&g,P0,card25("Exuberant Wolfbear"));
 g.state.objects.get_mut(&wolf).unwrap().counters.add(aperture_core::counters::CounterKind::PlusOnePlusOne,1);
 let human=battlefield_card(&g,P0,CardId::EliteVanguard);
 g.state.objects.get_mut(&human).unwrap().counters.add(aperture_core::counters::CounterKind::PlusOnePlusOne,1);
 let (_wolf,human)=attack_to_choice(&mut g);
 submit_ok(&mut g,P0,Action::AnswerTriggerChoice{use_ability:true});
 while !g.state.stack.is_empty(){let p=g.decision_owner().unwrap();submit_ok(&mut g,p,Action::Pass);}
 assert_eq!(g.state.object(human).power(),5,"base 5/5 from current Wolfbear + existing counter after setter");
 assert_eq!(g.state.object(human).toughness(),5);
 assert!(g.state.effects.iter().any(|e|e.kind==ContinuousKind::SetBasePowerToughness{power:5,toughness:5}));
}

#[test]
fn declining_leaves_human_unchanged_and_forged_nonhuman_target_refused() {
