cat >> crates/core/tests/issue17_slice30.rs <<'EOF'

use aperture_core::*;
use common::*;
fn card30(n:&str)->CardId{catalog::by_name(n).unwrap()}
fn drain(g:&mut Game){for _ in 0..128{if g.state.pending.is_some()||g.state.stack.is_empty(){return;}let p=g.decision_owner().unwrap();submit_ok(g,p,Action::Pass);}panic!("settle");}

#[test]
fn saddle_uses_other_untapped_creatures_and_grants_trample_on_attack() {
 let mut g=fixture(3001).battlefield(P0,&[card30("Drover Grizzly"),CardId::GrizzlyBears,CardId::EliteVanguard]).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
 let mount=battlefield_card(&g,P0,card30("Drover Grizzly"));
 let helper=battlefield_card(&g,P0,CardId::GrizzlyBears);
 let human=battlefield_card(&g,P0,CardId::EliteVanguard);
 let offers:Vec<_>=g.legal_actions().into_iter().filter(|a|matches!(&a.action,Action::SaddleMount{source,..} if *source==mount)).collect();
 assert!(!offers.is_empty(),"saddle must be offered");
 let action=offers.into_iter().find(|a|match &a.action{Action::SaddleMount{creatures,..}=>creatures==&vec![helper],_=>false}).expect("minimal helper offer").action;
 submit_ok(&mut g,P0,action);
 assert!(g.state.object(helper).tapped,"helper tapped as cost");
 drain(&mut g);
 assert!(g.state.effects.iter().any(|e|e.kind==ContinuousKind::Saddled&&e.target==mount));
 let mut log=Vec::new();
 assert!(run_until(&mut g,&mut log,|g|g.state.turn.step==Step::DeclareAttackers&&g.state.pending.is_some(),64));
 submit_ok(&mut g,P0,Action::DeclareAttackers{attackers:vec![mount],defender:Some(P1)});
 assert!(run_until(&mut g,&mut log,|g|g.state.stack.is_empty(),64));
 assert!(g.state.effects.iter().any(|e|e.kind==ContinuousKind::GrantsTrample&&e.target==helper));
 assert!(g.state.effects.iter().any(|e|e.kind==ContinuousKind::GrantsTrample&&e.target==human));
}

#[test]
fn unsaddled_attack_does_not_grant_and_invalid_saddles_are_refused() {
 let mut g=fixture(3002).battlefield(P0,&[card30("Drover Grizzly"),CardId::GrizzlyBears]).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
 let mount=battlefield_card(&g,P0,card30("Drover Grizzly"));
 let helper=battlefield_card(&g,P0,CardId::GrizzlyBears);
 let mut log=Vec::new();
 assert!(run_until(&mut g,&mut log,|g|g.state.turn.step==Step::DeclareAttackers&&g.state.pending.is_some(),64));
 submit_ok(&mut g,P0,Action::DeclareAttackers{attackers:vec![mount],defender:Some(P1)});
 drain(&mut g);
 assert!(!g.state.effects.iter().any(|e|e.kind==ContinuousKind::GrantsTrample));
 let before=g.state.clone();
 let err=g.submit_action(P0,Action::SaddleMount{source:mount,creatures:vec![mount]}).expect_err("self cannot be helper");
 assert_eq!(g.state,before);
 assert!(format!("{err:?}").contains("helpers"));
 g.state.objects.get_mut(&helper).unwrap().tapped=true;
 let err=g.submit_action(P0,Action::SaddleMount{source:mount,creatures:vec![helper]}).expect_err("tapped helper");
 assert_eq!(g.state,before);
 assert!(format!("{err:?}").contains("helpers"));
