 let offers:Vec<_>=g.legal_actions().into_iter().filter(|a|matches!(&a.action,Action::SaddleMount{source,..} if *source==mount)).collect();
 assert!(!offers.is_empty(),"saddle must be offered");
 let action=offers.into_iter().find(|a|match &a.action{Action::SaddleMount{creatures,..}=>creatures==&vec![helper],_=>false}).expect("minimal helper offer").action;
 submit_ok(&mut g,P0,action);
