use aperture_core::*;
use common::*;
fn card41(n:&str)->CardId{catalog::by_name(n).unwrap()}
fn drain(g:&mut Game){for _ in 0..128{if g.state.pending.is_some()||g.state.stack.is_empty(){return;}let p=g.decision_owner().unwrap();submit_ok(g,p,Action::Pass);}panic!("settle");}

#[test]
fn earth_king_really_casts_and_creates_distinct_four_four_bear() {
    let mut g=fixture(4101).hand(P0,&[card41("The Earth King")]).battlefield(P0,&[CardId::Forest;4]).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let spell=hand_card(&g,P0,card41("The Earth King"));
    let cast=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::CastSpell{card,..} if *card==spell)).expect("offered cast").action;
    submit_ok(&mut g,P0,cast); drain(&mut g);
    let king=battlefield_card(&g,P0,card41("The Earth King"));
    let token=g.state.battlefield(P0).into_iter().find(|o|o.card==CardId::EarthKingBearToken).expect("4/4 Bear token");
    assert_eq!(token.power(),4); assert_eq!(token.toughness(),4);
    assert_eq!(g.state.object(token.id).card.def().colors,&[aperture_core::card::ManaColor::Green]);
    assert!(CardId::TOKEN_CARDS.contains(&CardId::EarthKingBearToken));
    assert!(catalog::by_name("Bear Token").is_none());
    assert_eq!(g.state.object(king).counters.get(aperture_core::counters::CounterKind::PlusOnePlusOne),0);
}

#[test]
fn attack_search_is_one_trigger_for_two_qualifiers_and_puts_basic_lands_tapped() {
    let mut g=fixture(4102).battlefield(P0,&[card41("The Earth King"),card41("Craw Wurm"),card41("Craw Wurm")]).library(P0,&[CardId::Forest,CardId::Island,CardId::GrizzlyBears,CardId::Forest,CardId::Forest]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let king=battlefield_card(&g,P0,card41("The Earth King"));
