#[test]
fn old_attachment_survives_until_equip_resolves_and_bounce_does_not_transfer() {
 let mut g=fixture(4203).hand(P0,&[card42("Lightning Greaves"),CardId::Unsummon]).battlefield(P0,&[CardId::Forest,CardId::Forest,CardId::Forest,CardId::Island,CardId::GrizzlyBears,CardId::GrizzlyBears]).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
 let greaves=hand_card(&g,P0,card42("Lightning Greaves")); cast42(&mut g,greaves);
 let bears:Vec<_>=g.state.battlefield(P0).into_iter().filter(|o|o.card==CardId::GrizzlyBears).map(|o|o.id).collect();
 equip(&mut g,greaves,bears[0]);
 let action=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::ActivateAbility{source,targets,..} if *source==greaves && targets==&vec![Target::Permanent(bears[1])])).unwrap().action;
 submit_ok(&mut g,P0,action);
 assert!(g.state.effects.iter().any(|e|matches!(e.kind,ContinuousKind::Equipped{..})&&e.target==bears[0]),"old attachment stays while equip is on stack");
 assert!(!g.state.effects.iter().any(|e|matches!(e.kind,ContinuousKind::Equipped{..})&&e.target==bears[1]));
 drain(&mut g);
 assert!(g.state.effects.iter().any(|e|matches!(e.kind,ContinuousKind::Equipped{..})&&e.target==bears[1]));
 let unsummon=hand_card(&g,P0,CardId::Unsummon);
 assert!(g.submit_action(P0,Action::CastSpell{card:unsummon,targets:vec![Target::Permanent(bears[1])]}).is_ok());
 drain(&mut g);
 assert!(!g.state.effects.iter().any(|e|matches!(e.kind,ContinuousKind::Equipped{..})&&e.target==bears[1]),"bounce ends attachment");
}

#[test]
fn attached_and_mid_equip_save_reload_have_identical_continuation() {
 let mut g=fixture(4204).hand(P0,&[card42("Swiftfoot Boots")]).battlefield(P0,&[CardId::Forest,CardId::Forest,CardId::Forest,CardId::Forest,CardId::Forest,CardId::GrizzlyBears,CardId::GrizzlyBears]).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
 let boots=hand_card(&g,P0,card42("Swiftfoot Boots")); cast42(&mut g,boots);
 let bears:Vec<_>=g.state.battlefield(P0).into_iter().filter(|o|o.card==CardId::GrizzlyBears).map(|o|o.id).collect();
 equip(&mut g,boots,bears[0]);
 let action=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::ActivateAbility{source,targets,..} if *source==boots && targets==&vec![Target::Permanent(bears[1])])).unwrap().action;
 submit_ok(&mut g,P0,action);
 assert!(!g.state.stack.is_empty(),"equip ability is on stack");
 let decks=vec![DeckList::parse_practice("A","40 Forest\n").unwrap(),DeckList::parse_practice("B","40 Forest\n").unwrap()];
