    assert!(!g.state.effects.iter().any(|e|matches!(e.kind,ContinuousKind::Equipped{..})&&e.source==Some(boots)),"source-left equip resolves without attachment");
    let recast=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::CastSpell{card,..} if *card==boots)).expect("recast offered").action;
    submit_ok(&mut g,P0,recast); drain(&mut g);
    assert!(!g.state.effects.iter().any(|e|matches!(e.kind,ContinuousKind::Equipped{..})&&e.source==Some(boots)),"old equip cannot attach a new incarnation");
}

