fn drain(g:&mut Game){for _ in 0..128{if g.state.pending.is_some()||g.state.stack.is_empty(){return;}let p=g.decision_owner().unwrap();submit_ok(g,p,Action::Pass);}panic!("settle");}
fn cast44(g:&mut Game,id:ObjectId){let a=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::CastSpell{card,..} if *card==id)).expect("offered cast").action;submit_ok(g,P0,a);drain(g);}

#[test]
fn spirit_casts_and_etb_search_reveals_snow_land_to_hand() {
 let mut g=fixture(4401).hand(P0,&[card44("Spirit of the Aldergard")]).battlefield(P0,&[CardId::Forest;5]).library(P0,&[CardId::Forest,card44("Snow-Covered Forest"),CardId::GrizzlyBears]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
 let spell=hand_card(&g,P0,card44("Spirit of the Aldergard"));
 cast44(&mut g,spell);
 assert!(matches!(g.state.pending,Some(Pending::SearchLibrary{remaining:1,..})));
 let (eligible,mode)=match &g.state.pending{Some(Pending::SearchLibrary{eligible,mode,..})=>(eligible.clone(),*mode),other=>panic!("{other:?}")};
 assert_eq!(mode,LibrarySearchMode::SnowLandToHand);
 assert_eq!(eligible.len(),1);
 assert_eq!(g.state.object(eligible[0]).card,card44("Snow-Covered Forest"));
 assert!(g.view_for(P1,&[]).pending.is_none(),"search is private");
 let pick=g.legal_actions().into_iter().find(|a|matches!(a.action,Action::SearchLibraryPick{..})).expect("snow land offered").action;
 submit_ok(&mut g,P0,pick);
 submit_ok(&mut g,P0,Action::SearchLibraryDone); drain(&mut g);
 let id=eligible[0];
 assert_eq!(g.state.object(id).zone,Zone::Hand);
 assert_eq!(g.state.player(P0).hand.last(),Some(&id));
 assert!(!g.state.battlefield(P0).iter().any(|o|o.id==id),"snow search does not put land onto battlefield");
 assert!(g.state.pending.is_none());
}

#[test]
fn static_counts_other_current_snow_permanents_only_and_excludes_self() {
 let mut g=fixture(4402).battlefield(P0,&[card44("Spirit of the Aldergard")]).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
 let spirit=battlefield_card(&g,P0,card44("Spirit of the Aldergard"));
 assert_eq!(g.state.object(spirit).power(),0);
 assert_eq!(g.state.object(spirit).toughness(),4);
 add_card_object(&mut g,P0,card44("Snow-Covered Forest"));
 g.recompute_layers_for_test();
 assert_eq!(g.state.object(spirit).power(),1);
 add_card_object(&mut g,P0,card44("Snow-Covered Forest"));
 g.recompute_layers_for_test();
 assert_eq!(g.state.object(spirit).power(),2);
 let opp=add_card_object(&mut g,P1,card44("Snow-Covered Forest"));
 g.recompute_layers_for_test();
 assert_eq!(g.state.object(spirit).power(),2,"opponent snow ignored");
 let _=opp;
}
EOF
cargo fmt --all; cargo test -q -p aperture-core --test issue17_slice44 2>&1 | tail -10

