#[test]
fn snow_search_fails_to_find_and_postpick_save_continues() {
    let mut g=fixture(4403).hand(P0,&[card44("Spirit of the Aldergard")]).battlefield(P0,&[CardId::Forest;5]).library(P0,&[CardId::Forest,CardId::GrizzlyBears]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let spell=hand_card(&g,P0,card44("Spirit of the Aldergard")); cast44(&mut g,spell);
    assert!(matches!(g.state.pending,Some(Pending::SearchLibrary{remaining:1,..})));
    let eligible=match &g.state.pending{Some(Pending::SearchLibrary{eligible,..})=>eligible.clone(),_=>panic!()};
    assert!(eligible.is_empty(),"no snow land exists in this library");
    let library_before=g.state.player(P0).library.clone();
    submit_ok(&mut g,P0,Action::SearchLibraryDone); drain(&mut g);
    assert!(g.state.pending.is_none());
    assert_eq!(g.state.player(P0).hand.len(),1,"no card added");
    assert_eq!(g.state.player(P0).library.len(),library_before.len());
    // Real eligible path: pick, save before Done, reload and finish identically.
    let mut g=fixture(4404).hand(P0,&[card44("Spirit of the Aldergard")]).battlefield(P0,&[CardId::Forest;5]).library(P0,&[card44("Snow-Covered Forest"),CardId::Forest]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let spell=hand_card(&g,P0,card44("Spirit of the Aldergard")); cast44(&mut g,spell);
    let pick=g.legal_actions().into_iter().find(|a|matches!(a.action,Action::SearchLibraryPick{..})).expect("snow pick").action;
    submit_ok(&mut g,P0,pick);
    assert!(matches!(g.state.pending,Some(Pending::SearchLibrary{remaining:0,..})));
    let decks=vec![DeckList::parse_practice("A","40 Forest\n").unwrap(),DeckList::parse_practice("B","40 Forest\n").unwrap()];
    let replay=Replay::new(g.state.seed,g.state.first_player,decks,AiSettings::default()).unwrap();
    let save=SessionSave::capture(&g,replay,Vec::new(),true);
    let loaded=SessionSave::from_json(&save.to_json()).expect("postpick snow search loads");
    let mut loaded=Game::from_state(loaded.game).unwrap();
    submit_ok(&mut g,P0,Action::SearchLibraryDone); drain(&mut g);
    submit_ok(&mut loaded,P0,Action::SearchLibraryDone); drain(&mut loaded);
    assert_eq!(loaded.state,g.state); assert_eq!(loaded.digest(),g.digest());
}
EOF
cargo fmt --all; cargo test -q -p aperture-core --test issue17_slice44 2>&1 | tail -10

