use aperture_core::*;
use common::*;
fn c54(n:&str)->CardId{catalog::by_name(n).unwrap()}
fn grave(g:&mut Game,p:PlayerId,c_:CardId){let id=ObjectId(g.state.next_object);g.state.next_object+=1;g.state.objects.insert(id,aperture_core::state::Object{id,card:c_,owner:p,controller:p,zone:Zone::Graveyard,commander:None,tapped:false,damage:0,summoning_sick:false,pump_power:0,pump_toughness:0,plus_one_counters:0,counters:Default::default(),paired_with:None});g.state.players[p as usize].graveyard.push(id);}

#[test]
fn begin_combat_mills_forces_attack_and_sets_indestructible_dynamic_body() {
    let mut g=fixture(5401)
        .hand(P0,&[c54("Ursine Monstrosity")])
        .battlefield(P0,&[CardId::Forest,CardId::Forest,CardId::Forest])
        .library(P0,&[CardId::GrizzlyBears,CardId::Forest,CardId::Forest])
        .library(P1,&[CardId::Forest;8])
        .main(P0,Step::PrecombatMain).build();
    grave(&mut g,P0,CardId::Forest);
    grave(&mut g,P0,CardId::Shock);
    let spell=hand_card(&g,P0,c54("Ursine Monstrosity"));
    let cast=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::CastSpell{card,..} if *card==spell)).expect("cast offered").action;
    submit_ok(&mut g,P0,cast);
    let mut log=Vec::new();
    assert!(run_until(&mut g,&mut log,|g|g.state.effects.iter().any(|e|e.kind==ContinuousKind::Indestructible),128));
    let ursine=battlefield_card(&g,P0,c54("Ursine Monstrosity"));
    assert_eq!(g.state.player(P0).graveyard.len(),3,"mill added a card to two existing");
    assert!(g.state.player(P0).graveyard.iter().any(|id|g.state.object(*id).card==CardId::GrizzlyBears));
    assert_eq!(g.state.object(ursine).power(),6,"three distinct graveyard card types");
    assert!(g.state.effects.iter().any(|e|matches!(e.kind,ContinuousKind::MustAttackThisCombat)&&e.controller==P1));
    let first=run_until(&mut g,&mut log,|g|g.state.turn.step==Step::DeclareAttackers&&g.state.pending.is_some(),128);
    assert!(first);
    let wrong=g.submit_action(P0,Action::DeclareAttackers{attackers:Vec::new(),defender:None});
    assert!(wrong.is_err(),"must attack the chosen opponent if able");
    submit_ok(&mut g,P0,Action::DeclareAttackers{attackers:vec![ursine],defender:Some(P1)});
    // Indestructible replacement through the lethal-damage/SBA path.
    g.state.objects.get_mut(&ursine).unwrap().damage=99;
    for _ in 0..4 { let p=g.decision_owner().unwrap(); submit_ok(&mut g,p,Action::Pass); if g.state.object(ursine).zone!=Zone::Battlefield {break;} }
    assert_eq!(g.state.object(ursine).zone,Zone::Battlefield,"indestructible survives lethal damage");
}
