use aperture_core::*;
use common::*;
fn c59(n:&str)->CardId{catalog::by_name(n).unwrap()}
fn drain(g:&mut Game){for _ in 0..128{if g.state.pending.is_some()||g.state.stack.is_empty(){return;}let p=g.decision_owner().unwrap();submit_ok(g,p,Action::Pass);}panic!("settle");}

#[test]
fn real_cast_landfall_tempts_and_chooses_ring_bearer() {
    let mut g=fixture(5901).hand(P0,&[c59("Dúnedain Rangers"),CardId::Forest]).battlefield(P0,&[CardId::Forest;4,CardId::GrizzlyBears]).library(P0,&[CardId::Forest;8]).library(P1,&[CardId::Forest;8]).main(P0,Step::PrecombatMain).build();
    let spell=hand_card(&g,P0,c59("Dúnedain Rangers"));
    let cast=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::CastSpell{card,..} if *card==spell)).expect("cast offered").action;
    submit_ok(&mut g,P0,cast); drain(&mut g);
    let land=hand_card(&g,P0,CardId::Forest);
    let play=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::PlayLand{card} if *card==land)).expect("land offered").action;
    submit_ok(&mut g,P0,play); drain(&mut g);
    assert!(matches!(g.state.pending,Some(Pending::RingTemptation{..})),"landfall must tempt");
    let bear=battlefield_card(&g,P0,CardId::GrizzlyBears);
    let choice=g.legal_actions().into_iter().find(|a|matches!(&a.action,Action::ChooseRingBearer{bearer} if bearer==&Some(bear))).expect("bearer offered").action;
    submit_ok(&mut g,P0,choice); drain(&mut g);
    assert_eq!(g.state.rings[P0 as usize].temptations,1);
    assert_eq!(g.state.rings[P0 as usize].bearer,Some(bear));
}
