impl Effect {
    pub fn describe(self) -> String {
        match self {
            Effect::Draw(n) => format!("draw {n}"),
            Effect::Scry(n) => format!("scry {n}"),
            Effect::Surveil(n) => format!("surveil {n}"),
            Effect::Damage(n) => format!("deal {n} damage to the target"),
            Effect::CounterTargetSpell => "counter target spell".to_string(),
            Effect::Pump(p, t) => format!("target creature gets {p:+}/{t:+} until end of turn"),
            Effect::EachPlayerSacrifice => "each player sacrifices a permanent".to_string(),
            Effect::ReturnToHand => "return the target creature to its owner's hand".to_string(),
            Effect::ReturnGraveyardCardToHand => {
                "return the target creature card from your graveyard to your hand".to_string()
            }
            Effect::PutOnTopOfLibrary => {
                "put the target creature on top of its owner's library".to_string()
            }
            Effect::ExileAndGainLife => {
                "exile the target creature; its controller gains life equal to its power"
                    .to_string()
            }
            ),
            rules: vec!["608.2b", "608.2c"],
        });
    }

    if let Some(pending) = &state.pending {
        let rules = match pending {
            Pending::Mulligan { .. } | Pending::BottomCards { .. } => vec!["103.5"],
            Pending::DeclareAttackers { .. } => vec!["508.1a"],
            Pending::DeclareBlockers { .. } => vec!["509.1a"],
            Pending::OrderCard { mode, .. } => match mode {
                OrderMode::Scry => vec!["701.22a"],
                OrderMode::Surveil => vec!["701.25a"],
            },
            Pending::Discard { .. } => vec!["514.1"],
            Pending::CombatDamageAssignment { .. } => vec!["510.1", "509.1h"],
            Pending::ApnapSacrifice { .. } => vec!["101.4", "701.21a"],
            Pending::ApnapReveal { .. } => vec!["101.4", "701.9a"],
            Pending::CommanderReturn { .. } => vec!["903.9a"],
            Pending::CommanderReplacement { .. } | Pending::CommanderDraw { .. } => {
                vec!["903.9b"]
            }
            Pending::TriggerTarget { .. } => vec!["603.3d"],
            Pending::TriggerChoice { .. } => vec!["603.5"],
            Pending::TriggerMode { .. } => vec!["603.3c", "700.2b"],
            Pending::RingTemptation { .. } => vec!["701.54a"],
            Pending::LegendaryChoice { .. } => vec!["704.5j"],
            Pending::TopCardChoice { .. } => vec!["701.20e"],
            Pending::SearchLibrary { .. } => vec!["701.23"],
        };
        let text = if pending.player() != viewer
        match pending {
            Pending::RingTemptation { eligible, .. } => {
                let mut out: Vec<LegalAction> = eligible
